def solve(coins, amount):
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    valid = [c for c in coins if c > 0]
    if not valid:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in valid:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

